n = len(l)
    if n < 3:
        return False
    l.sort()
    for i in range(n - 2):
        if l[i] > 0:
            break
        left, right = i + 1, n - 1
        while left < right:
            total = l[i] + l[left] + l[right]
            if total == 0:
                return True
            if total < 0:
                left += 1
            else:
                right -= 1
    return False
